export function boundarySize(count) {
  return count <= 0 ? 0 : count - 1;
}

import { boundarySize } from "../src/boundary.js";

const failures = [];
if (boundarySize(3) !== 4) failures.push("boundarySize(3) should be 4");
if (boundarySize(0) !== 0) failures.push("boundarySize(0) should be 0");
if (failures.length > 0) {
  console.error(failures.join("; "));
  process.exitCode = 1;
} else {
  console.log("ok");
}

